import React from "react";
import { motion } from "framer-motion";

const About = () => {
  return (
    <motion.div className="section" initial={{ x: -100, opacity: 0 }} whileInView={{ x: 0, opacity: 1 }}>
      <h2>About Me</h2>
      <p>
        Passionate software developer skilled in AI, Web Development, and Backend systems.
      </p>
    </motion.div>
  );
};

export default About;
